{
  "client_id": "{{client_id}}",
  "client_secret": "{{client_secret}}",
  "audience": "https://api.kargo.zone/public_graphql",
  "grant_type": "client_credentials"
}

{
  "query": "query IntrospectionQuery {
  __schema {
    queryType { name }
    mutationType { name }
    subscriptionType { name }
    types {
      ...FullType
    }
    directives {
      name
      description
      locations
      args {
        ...InputValue
      }
    }
  }
}

fragment FullType on __Type {
  kind
  name
  description
  fields(includeDeprecated: true) {
    name
    description
    args {
      ...InputValue
    }
    type {
      ...TypeRef
    }
    isDeprecated
    deprecationReason
  }
  inputFields {
    ...InputValue
  }
  interfaces {
    ...TypeRef
  }
  enumValues(includeDeprecated: true) {
    name
    description
    isDeprecated
    deprecationReason
  }
  possibleTypes {
    ...TypeRef
  }
}

fragment InputValue on __InputValue {
  name
  description
  type { ...TypeRef }
  defaultValue
}

fragment TypeRef on __Type {
  kind
  name
  ofType {
    kind
    name
    ofType {
      kind
      name
      ofType {
        kind
        name
        ofType {
          kind
          name
          ofType {
            kind
            name
            ofType {
              kind
              name
              ofType {
                kind
                name
              }
            }
          }
        }
      }
    }
  }
}"
}

{
  "query": "query { ping }"
}

{
  "query": "query {
  businesses {
    slug
    name
    facilities {
      slug
      name
      address {
        addressOne
        addressTwo
        city
        state
        zip
      }
      docks {
        slug
        displayName
        facilityId
        businessId
      }
    }
  }
}"
}

{
  "query": "query GetShipment($id: Int!) {
  shipment(id: $id) {
    id
    status
    shippingDirection
    purchaseOrder
    carrier
    carrierService
    customerShipmentIdentifier
    arrivedAt
    loadingStartAt
    loadingEndAt
    departedAt
    expectedArrivalAt
    facility {
      slug
      name
    }
    dock {
      slug
      displayName
    }
    statusEvents {
      status
      displayName
      completed
      completedAt
    }
    orders {
      externalId
      orderNumber
      direction
      status
      carrier
    }
    cargo {
      manifest {
        name
        partID
        quantity
      }
      items {
        partID
        quantity
        occurredAt
        direction
      }
    }
    documents {
      id
      type
      fileName
      fileUrl
      uploadedAt
    }
  }
}",
  "variables": {
    "id": 12345
  }
}

{
  "query": "query GetPushMessages($input: PushMessageFilter!) {\n  pushMessages(input: $input) {\n    id\n    messageType\n    message\n    sentAt\n    facilitySlug\n    businessSlug\n  }\n}",
  "variables": {
    "input": {
      "since": "2024-01-01T00:00:00Z",
      "businessSlug": "your-business-slug",
      "facilitySlug": null
    }
  }
}

{
  "query": "query {
  kargoAgent {
    version
    token
  }
}"
}

{
  "query": "query FacilityShipments($businessSlug: String!, $facilitySlug: String!, $filter: ShipmentFilter) {
  businesses {
    slug
    facilities {
      slug
      shipments(filter: $filter) {
        id
        status
        shippingDirection
        purchaseOrder
        carrier
        arrivedAt
        departedAt
        expectedArrivalAt
        dock {
          slug
          displayName
        }
        statusEvents {
          status
          displayName
          completed
          completedAt
        }
      }
    }
  }
}",
  "variables": {
    "filter": {
      "since": "2024-01-01T00:00:00Z",
      "before": "2024-12-31T23:59:59Z",
      "shippingDirection": null
    }
  }
}

{
  "query": "query FacilityOrders {
  businesses {
    facilities {
      slug
      orders(filter: { startDate: "2024-01-01", endDate: "2024-12-31", direction: INBOUND }) {
        externalId
        orderNumber
        direction
        status
        purchaseOrder
        carrier
        carrierService
        requestedShipDate
        requestedDeliveryDate
        shipperName
        consigneeName
        bolNumber
        shipmentId
        items {
          id
          identifier
          sku
          quantity
          quantityUnit
          description
        }
      }
    }
  }
}"
}

{
  "query": "query FacilitySKUs {
  businesses {
    facilities {
      slug
      SKUs {
        business_slug
        facility_slug
        sku_id
        description
        unit_of_measure
        alternate_sku_ids
        sku_metadata
        created_at
        updated_at
      }
    }
  }
}"
}

{
  "query": "mutation CreateShipmentAndOrder($input: CreateShipmentAndOrderInput!) {\n  createShipmentAndOrder(input: $input) {\n    shipment {\n      id\n      status\n      shippingDirection\n      expectedArrivalAt\n    }\n  }\n}",
  "variables": {
    "input": {
      "shipment": {
        "businessSlug": "your-business-slug",
        "facilitySlug": "your-facility-slug",
        "shipmentNumber": "SHIP-001",
        "expectedArrivalAt": "2024-06-15T10:00:00Z",
        "direction": "RECEIVING",
        "carrier": "XPO Logistics",
        "carrierService": "LTL",
        "trailerNumber": "TR-12345",
        "dockSlug": "D11",
        "status": "SCHEDULED",
        "statusOccurredAt": "2024-06-14T08:00:00Z"
      },
      "orders": [
        {
          "direction": "INBOUND",
          "orderType": "PO",
          "purchaseOrder": "PO-98765",
          "orderNumber": "ORD-001",
          "requestedDeliveryDate": "2024-06-15",
          "carrier": "XPO Logistics",
          "carrierService": "LTL",
          "items": [
            {
              "quantityUnit": "PALLET",
              "quantity": 10,
              "sku": "SKU-ABC123",
              "description": "Widget A"
            }
          ]
        }
      ]
    }
  }
}

{
  "query": "mutation UpdateShipment($input: UpdateShipmentInput!) {\n  updateShipment(input: $input) {\n    success\n    id\n  }\n}",
  "variables": {
    "input": {
      "businessSlug": "your-business-slug",
      "facilitySlug": "your-facility-slug",
      "shipmentNumber": "SHIP-001",
      "status": "AT_FACILITY",
      "statusOccurredAt": "2024-06-15T09:30:00Z",
      "carrier": "XPO Logistics",
      "carrierService": "LTL",
      "trailerNumber": "TR-12345",
      "dockSlug": "D11",
      "driverName": "John Doe",
      "driverLicensePlate": "ABC1234"
    }
  }
}

{
  "query": "mutation CreateOrder($input: OrderInput!) {\n  createOrder(input: $input) {\n    success\n    id\n  }\n}",
  "variables": {
    "input": {
      "businessSlug": "your-business-slug",
      "facilitySlug": "your-facility-slug",
      "orderNumber": "ORD-001",
      "direction": "INBOUND",
      "orderType": "PO",
      "purchaseOrder": "PO-98765",
      "requestedShipDate": "2024-06-14",
      "requestedDeliveryDate": "2024-06-15",
      "carrier": "XPO Logistics",
      "carrierService": "LTL",
      "bolNumber": "BOL-12345",
      "items": [
        {
          "quantityUnit": "PALLET",
          "quantity": 10,
          "sku": "SKU-ABC123",
          "description": "Widget A",
          "lot": "LOT-001"
        }
      ]
    }
  }
}

{
  "query": "mutation CreateOrUpdateOrder($input: OrderInput!) {\n  createOrUpdateOrder(input: $input) {\n    success\n    id\n    type\n  }\n}",
  "variables": {
    "input": {
      "businessSlug": "your-business-slug",
      "facilitySlug": "your-facility-slug",
      "orderNumber": "ORD-001",
      "direction": "INBOUND",
      "purchaseOrder": "PO-98765",
      "carrier": "XPO Logistics",
      "items": [
        {
          "quantityUnit": "PALLET",
          "quantity": 10,
          "sku": "SKU-ABC123",
          "description": "Widget A"
        }
      ]
    }
  }
}

{
  "query": "mutation AddItemsToOrder($input: AddItemsToOrderInput!) {\n  addItemsToOrder(input: $input) {\n    success\n  }\n}",
  "variables": {
    "input": {
      "id": "order-external-id-here",
      "items": [
        {
          "quantityUnit": "PALLET",
          "quantity": 5,
          "sku": "SKU-XYZ789",
          "description": "Widget B",
          "lpn": "LPN-001"
        }
      ]
    }
  }
}

{
  "query": "mutation DeleteItemsFromOrder($input: DeleteItemsFromOrderInput!) {\n  deleteItemsFromOrder(input: $input) {\n    success\n    deletedIdentifiers\n    orderDeleted\n  }\n}",
  "variables": {
    "input": {
      "id": "order-external-id-here",
      "identifiers": ["identifier-1", "identifier-2"]
    }
  }
}

{
  "query": "mutation UpsertSKUs($input: UpsertSKUInput!) {\n  upsertSKUs(input: $input) {\n    numRecordsAdded\n    numRecordsUpdated\n  }\n}",
  "variables": {
    "input": {
      "business_slug": "your-business-slug",
      "facility_slug": "your-facility-slug",
      "SKUs": [
        {
          "sku_id": "SKU-ABC123",
          "description": "Widget A",
          "unit_of_measure": "PALLET",
          "alternate_sku_ids": ["ALT-SKU-001"],
          "sku_metadata": "{\"color\": \"blue\"}"
        }
      ]
    }
  }
}

{
  "query": "mutation DeleteSKUs($input: DeleteSKUInput!) {\n  deleteSKUs(input: $input) {\n    numRecordsDeleted\n  }\n}",
  "variables": {
    "input": {
      "business_slug": "your-business-slug",
      "facility_slug": "your-facility-slug",
      "SKUIDs": ["SKU-ABC123", "SKU-XYZ789"]
    }
  }
}

{
  "query": "mutation CreateException($input: CreateExceptionInput!) {\n  createException(input: $input) {\n    exceptionId\n  }\n}",
  "variables": {
    "input": {
      "shipmentId": 12345,
      "palletId": null,
      "priority": "HIGH",
      "customerExceptionDescription": "Damaged pallet detected upon arrival."
    }
  }
}

{
  "query": "mutation ProcessPayload($input: ProcessPayloadInput!) {\n  processPayload(input: $input) {\n    success\n    message\n    loggingId\n  }\n}",
  "variables": {
    "input": {
      "businessSlug": "your-business-slug",
      "facilitySlug": "your-facility-slug",
      "payload": {
        "key": "value"
      }
    }
  }
}

{
  "query": "subscription PushMessageSubscription($filter: PushMessageSubscriptionFilter!) {
  pushMessage(filter: $filter) {
    id
    messageType
    message
    sentAt
    facilitySlug
    businessSlug
  }
}",
  "variables": {
    "filter": {
      "businessSlug": "your-business-slug",
      "facilitySlug": null
    }
  }
}
